+    extractOutageCodes: extractOutageCodes,
+    outageResetHeaderOf: outageResetHeaderOf,
     parkLabelOf: parkLabelOf,
     probeEveryOf: probeEveryOf,
     probeCommandOf: probeCommandOf,

