        }
        console.log('Bounded outage resume not attempted (' + (outageResume.reason || 'unknown') + ') — continuing to the existing reset path.');
        return null;
    }
    var resume = feedbackLoop.resumeOnceForMissingResponse({
        ticketKey: ticketKey,
        customParams: customParams
    });
    if (!resume.attempted) {
